	public static AnimationDefinition of(MinotaurAnim anim) {
		return switch (anim) {
			case IDLE -> IDLE;
			case WALK -> WALK;
			case GORE -> GORE;
			case CHARGE -> CHARGE;
			case STOMP -> STOMP;
			case FRENZY -> FRENZY;
			case STAGGER -> STAGGER;
			case PHASE -> PHASE;
			case INTRO -> INTRO;
			case HURT -> HURT;
			case DEATH -> DEATH;
		};
	}

	/** Every animation, in MinotaurAnim's order. */
	public static List<AnimationDefinition> all() {
		return Arrays.stream(MinotaurAnim.values()).map(MinotaurAnimations::of).toList();
	}
